#include "ordinary_multiheads_clustering.hpp"
#include "clipper2/clipper.h"
#include <iostream>
using namespace study;using namespace study::recovered;
int main(){try{size_t cases=0,total=0,compounds=0;for(size_t kind=0;kind<6;++kind){Input input;input.width=160;input.height=100;input.pitch=1;input.randomSeed=27;PartInput part;part.quantity=kind==4?13:12;part.poses={{kind==5?90.:0.}};
 part.polygon=kind==1?Polygon{{0,0},{25,0},{25,8},{11,8},{11,21},{0,21}}:kind==2?Polygon{{0,0},{30,30},{30,40},{0,10}}:Polygon{{0,0},{30,0},{30,20},{0,20}};input.parts.push_back(part);if(kind==3){part.quantity=9;part.polygon={{0,0},{15,0},{15,12},{0,12}};input.parts.push_back(part);}
 MultiheadsClusteringProgram program;program.child.kind=MultiheadsChildKind::Clustering;program.child.parameters={3,1,80,(kind==1||kind==2||kind==4||kind==5)?3:-1};program.child.clusterTrials=4;program.child.randomCluster=false;program.child.halfClusters=kind!=1&&kind!=2&&kind!=4&&kind!=5;program.random=Random(27);
 MultiheadsClusteringTrace trace;Budget budget(45);const auto result=ordinaryMultiheadsClusteringResult(input,budget,program,&trace);require(trace.modules>0&&trace.candidates>0&&trace.compoundCommits>0,PN2S_INTERNAL,"Actual clustering did not generate and commit compounds");require(trace.temporaryValidations==trace.temporaryRemovals&&trace.temporaryValidations>0,PN2S_INTERNAL,"Compound temporary admission failed to roll back");
 require(valid_layout(input,result.output),PN2S_INTERNAL,"Actual clustering layout is invalid");double maxOverlap=0;for(size_t i=0;i<result.output.placements.size();++i)for(size_t j=0;j<i;++j){Clipper2Lib::PathsD paths;for(const auto index:{i,j}){const auto &p=result.output.placements[index];const auto &partInput=input.parts[p.group];const auto polygon=transform(partInput.polygon,partInput.pivot,partInput.poses[p.poseIndex]);Clipper2Lib::PathD path;for(auto q:polygon)path.push_back({q.x+double(p.x)/1e6,q.y+double(p.y)/1000.});paths.push_back(std::move(path));}const auto value=std::abs(Clipper2Lib::Area(Clipper2Lib::Intersect(Clipper2Lib::PathsD{paths[0]},Clipper2Lib::PathsD{paths[1]},Clipper2Lib::FillRule::NonZero,6)));maxOverlap=std::max(maxOverlap,value);}require(maxOverlap==0,PN2S_INTERNAL,"Independent Clipper found clustering overlap");
 size_t linked=0;for(const auto &owner:result.placements)if(owner->group58){++linked;for(const auto &slot:owner->group58->members){const auto sister=std::static_pointer_cast<WarmPlacement>(slot.lock());require(bool(sister)&&sister->group58==owner->group58,PN2S_INTERNAL,"Committed cluster lost shared sister owners");require(sister->x48==owner->x48,PN2S_INTERNAL,"Clustering lost head X alignment");}}
 const auto constraints=multiheadsShakerConstraints(result.placements);require(!constraints.empty()&&linked>=2*trace.compoundCommits,PN2S_INTERNAL,"Clustering result lost Shaker links");size_t requested=0;for(const auto &partInput:input.parts)requested+=size_t(partInput.quantity);if(kind!=4)require(result.output.placements.size()==requested,PN2S_INTERNAL,"Clustering left demand unplaced in the roomy test stock");else require(result.output.placements.size()==12,PN2S_INTERNAL,"Fixed3-head clustering did not preserve its12/13 demand behavior");
 std::cout<<"{\"case\":"<<kind<<",\"placed\":"<<result.output.placements.size()<<",\"requested\":"<<requested<<",\"modules\":"<<trace.modules<<",\"candidates\":"<<trace.candidates<<",\"compoundCommits\":"<<trace.compoundCommits<<",\"singleCommits\":"<<trace.singleCommits<<",\"temporaryValidations\":"<<trace.temporaryValidations<<",\"linked\":"<<linked<<",\"strictValid\":true,\"maximumOverlap\":"<<maxOverlap<<"}\n";
 ++cases;total+=result.output.placements.size();compounds+=trace.compoundCommits;}
 std::cout<<"{\"pass\":true,\"cases\":"<<cases<<",\"placements\":"<<total<<",\"compoundCommits\":"<<compounds<<"}\n";return 0;}catch(const std::exception &error){std::cerr<<error.what()<<'\n';return 1;}}
